	@Inject
	public ActivityDiagramGrammarAccess(GrammarProvider grammarProvider,
			DmlGrammarAccess gaDml,
			TerminalsGrammarAccess gaTerminals) {
		this.grammar = internalFindGrammar(grammarProvider);
		this.gaDml = gaDml;
		this.gaTerminals = gaTerminals;
		this.pActivityDiagram = new ActivityDiagramElements();
		this.pPhysicalContext = new PhysicalContextElements();
		this.pActivity = new ActivityElements();
		this.pConditionalActivity = new ConditionalActivityElements();
		this.pBooleanOp = new BooleanOpElements();
		this.pOutcome = new OutcomeElements();
		this.pCheckParameterCondition = new CheckParameterConditionElements();
		this.eUnitTime = new UnitTimeElements();
	}
	
	protected Grammar internalFindGrammar(GrammarProvider grammarProvider) {
		Grammar grammar = grammarProvider.getGrammar(this);
		while (grammar != null) {
			if ("com.smr.activity.dsl.ActivityDiagram".equals(grammar.getName())) {
				return grammar;
			}
			List<Grammar> grammars = grammar.getUsedGrammars();
			if (!grammars.isEmpty()) {
				grammar = grammars.iterator().next();
			} else {
				return null;
			}
		}
		return grammar;
	}
	
	@Override
	public Grammar getGrammar() {
		return grammar;
	}
	
	
